import com.keepcalm.placementportal.entity.common.*;import com.keepcalm.placementportal.exception.DomainException;import com.keepcalm.placementportal.models.communication.CommunicationDtos.*;import com.keepcalm.placementportal.repository.communication.AnnouncementRepository;import lombok.RequiredArgsConstructor;import org.springframework.cache.annotation.CacheEvict;import org.springframework.cache.annotation.Cacheable;import org.springframework.data.domain.Pageable;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.Map;
@Service @RequiredArgsConstructor public class AnnouncementService{private final AnnouncementRepository announcements;private final CurrentUserService current;private final AuditService audit;@Cacheable(cacheNames="announcements",keyGenerator="institutionAwareKeyGenerator",sync=true) @Transactional(readOnly=true)public PagedResponse<AnnouncementDto> list(Pageable p){return PagedResponse.from(announcements.visible(current.principal().institutionId(),current.principal().role(),Instant.now(),p).map(this::dto));}@Cacheable(cacheNames="announcements",keyGenerator="institutionAwareKeyGenerator",sync=true) @Transactional(readOnly=true)public AnnouncementDto get(Long id){Announcement a=announcement(id);if(a.getPublishedAt()==null||a.isArchived())throw DomainException.notFound("Announcement not found");return dto(a);}@CacheEvict(cacheNames="announcements",allEntries=true) @Transactional public AnnouncementDto create(AnnouncementUpsert r){Announcement a=new Announcement();User actor=current.getCurrentUser();a.setInstitution(actor.getInstitution());a.setCreatedBy(actor);apply(a,r);announcements.save(a);audit.record("ANNOUNCEMENT_CREATED","Announcement",a.getId(),Map.of());return dto(a);}@CacheEvict(cacheNames="announcements",allEntries=true) @Transactional public AnnouncementDto update(Long id,AnnouncementUpsert r){Announcement a=announcement(id);apply(a,r);audit.record("ANNOUNCEMENT_UPDATED","Announcement",id,Map.of());return dto(a);}@CacheEvict(cacheNames="announcements",allEntries=true) @Transactional public void delete(Long id){Announcement a=announcement(id);a.setArchived(true);audit.record("ANNOUNCEMENT_ARCHIVED","Announcement",id,Map.of());}@CacheEvict(cacheNames="announcements",allEntries=true) @Transactional public AnnouncementDto publish(Long id){Announcement a=announcement(id);a.setPublishedAt(Instant.now());audit.record("ANNOUNCEMENT_PUBLISHED","Announcement",id,Map.of());return dto(a);}private Announcement announcement(Long id){return announcements.findByIdAndInstitutionId(id,current.principal().institutionId()).orElseThrow(()->DomainException.notFound("Announcement not found"));}private void apply(Announcement a,AnnouncementUpsert r){a.setTitle(r.title().trim());a.setContent(r.content().trim());a.setAudienceRole(r.audienceRole());a.setExpiresAt(r.expiresAt());}private AnnouncementDto dto(Announcement a){return new AnnouncementDto(a.getId(),a.getTitle(),a.getContent(),a.getAudienceRole(),a.getPublishedAt(),a.getExpiresAt(),a.getVersion());}}
